    for kind in [0, 1, 2, 10] {
        app.fx_add_kind = kind;
        app.add_effect();
        app.confirm_effect_type_edit();
    }
    app.fx_selection = app
        .song
        .insert_rack
        .order
        .get(1)
        .copied()
        .map(FxRackSelection::Effect)
        .unwrap_or(FxRackSelection::Insert);
