        a.screen = Screen::TrackerFiles;
        a.choose_pattern_clear();
        dispatch_pad(PadAction::Item3, true, &mut a, Path::new("/none"), &tx);
        assert_eq!(
            a.overlay.as_ref().map(|overlay| overlay.kind),
            Some(OverlayKind::TrackerPatternLength)
        );
