    #[test]
    fn ideas_enter_encoder_and_mouse_all_inspect_while_load_stays_explicit() {
        let p = presets();
        let (tx, _rx) = mpsc::channel();
        let setup = || {
            let mut a = app(&p);
            a.screen = Screen::Ideas;
            a.controller_layout = ControllerLayout::Eight;
            a.ideas = vec!["missing-idea".into()];
            a
        };

        let mut keyboard = setup();
        key(KeyCode::Enter, &mut keyboard, Path::new("/none"), &tx);
        assert_eq!(keyboard.status, "IDEA INSPECT FAILED · choose another");

        let mut encoder = setup();
        dispatch_encoder(
            crate::pads::EncoderAction::Select,
            &mut encoder,
            Path::new("/none"),
            &tx,
        );
        assert_eq!(encoder.status, "IDEA INSPECT FAILED · choose another");

        let mut pointer = setup();
        render_app(&mut pointer, 40, 20);
        mouse(
            MouseEvent {
                kind: MouseEventKind::Down(MouseButton::Left),
                column: pointer.hits.list.x,
                row: pointer.hits.list.y,
                modifiers: crossterm::event::KeyModifiers::NONE,
            },
            &mut pointer,
            Path::new("/none"),
            &tx,
        );
        assert_eq!(pointer.status, "IDEA INSPECT FAILED · choose another");

        perform(
            Action::LoadIdea,
            &mut pointer,
            Path::new("/none"),
            Some(&tx),
        );
        assert_eq!(pointer.status, "IDEA READ FAILED · choose another");
    }

