    #[test]
    fn routing_failures_retain_the_entered_draft_row_and_retry_context() {
        let p = presets();
        let mut invalid = app(&p);
        invalid.screen = Screen::Routing;
        invalid.routing.selected = 4;
        invalid.begin_routing_edit();
        invalid
            .routing
            .draft
            .as_mut()
            .unwrap()
            .config
            .midi_performance_input_matches = vec!["Keys".into(), "Keys".into()];
        invalid.confirm_routing_edit(Path::new("/none"));
        assert!(invalid.routing.draft.is_some());
        assert_eq!(invalid.routing.selected, 4);
        assert_eq!(invalid.status, "ROUTING INVALID · fix field");

        let missing_parent = std::env::temp_dir().join(format!(
            "shr-routing-missing-{}-{}",
            std::process::id(),
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        fs::write(&missing_parent, b"not a directory").unwrap();
        let mut save_failure = app(&p);
        save_failure.screen = Screen::Routing;
        save_failure.routing.selected = 2;
        save_failure.begin_routing_edit();
        save_failure
            .routing
            .draft
            .as_mut()
            .unwrap()
            .config
            .midi_controller_musical_input = true;
        let expected_layout = save_failure
            .routing
            .draft
            .as_ref()
            .unwrap()
            .controller
            .layout;
        save_failure.confirm_routing_edit(&missing_parent);
        let retained = save_failure.routing.draft.as_ref().unwrap();
        assert!(retained.config.midi_controller_musical_input);
        assert_eq!(retained.controller.layout, expected_layout);
        assert_eq!(save_failure.routing.selected, 2);
        assert!(save_failure.status.contains("draft kept"));
        assert!(save_failure.cancel_routing_edit());
        assert!(save_failure.routing.draft.is_none());
        fs::remove_file(missing_parent).unwrap();
    }

    #[test]
    fn routing_confirm_is_atomic_and_migrates_legacy_audiobox_identity() {
        let base = std::env::temp_dir().join(format!(
            "shr-routing-editor-{}-{}",
            std::process::id(),
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        fs::create_dir_all(&base).unwrap();
        let p = presets();
        let mut a = app(&p);
        a.config.external_midi.enabled = true;
        a.config.external_midi.output_match = "AudioBox USB 96 AudioBox USB 96 MIDI 1".into();
        a.config.save(&base.join("shsynth.conf")).unwrap();
        let controller = a.controller_config.read().unwrap().clone();
        controller.save(&base.join("controller.conf")).unwrap();
        a.routing_outputs = vec!["AudioBox USB 96:AudioBox USB 96 MIDI 1 32:0".into()];
        a.routing.selected = 1;
        a.begin_routing_edit();
        a.adjust_routing_draft(1);
        let routing = &mut a.routing.draft.as_mut().unwrap().config.external_midi;
        routing.profile = "roland-d-50".into();
        a.confirm_routing_edit(&base);

        let saved = RuntimeConfig::load(&base.join("shsynth.conf")).unwrap();
        assert_eq!(
            saved.external_midi.output_match,
            "AudioBox USB 96:AudioBox USB 96 MIDI 1"
        );
        assert!(!saved.external_midi.output_match.ends_with("32:0"));
        assert_eq!(saved.external_midi.profile, "roland-d-50");
        assert_ne!(
            saved.midi_controller_musical_input,
            RuntimeConfig::default().midi_controller_musical_input
        );
        assert!(fs::read_dir(&base)
            .unwrap()
            .filter_map(std::result::Result::ok)
            .any(|entry| entry.file_name().to_string_lossy().contains(".bak-")));
        fs::remove_dir_all(&base).unwrap();
    }

