        assert_eq!(a.selected, p.len() - 1);
        render_app(&mut a, 40, 20);
        assert!(a.offset > 0, "wrapped preset must be scrolled into view");
        perform(Action::Down, &mut a, Path::new("/none"), None);
        assert_eq!(a.selected, 0);

