    #[test]
    fn eight_five_and_four_control_layouts_select_pages_without_losing_encoder_navigation() {
        let p = presets();
        let (tx, rx) = mpsc::channel();
        let mut eight = app(&p);
        eight.screen = Screen::Tracker;
        tx.send(MidiEvent::Pad(crate::pads::PadAction::Page2, true))
            .unwrap();
        tx.send(MidiEvent::Pad(crate::pads::PadAction::Item1, true))
            .unwrap();
        drain(&rx, &mut eight, Path::new("/none"), &tx);
        assert_eq!(eight.menu_page(), 1);
        assert_eq!(
            eight.overlay.as_ref().map(|overlay| overlay.kind),
            Some(OverlayKind::TrackerPage)
        );

        let mut five = app(&p);
        five.screen = Screen::Tracker;
        five.controller_layout = ControllerLayout::Five;
        five.select_menu_page(1);
        tx.send(MidiEvent::Pad(crate::pads::PadAction::Item1, true))
            .unwrap();
        drain(&rx, &mut five, Path::new("/none"), &tx);
        assert_eq!(
            five.overlay.as_ref().map(|overlay| overlay.kind),
            Some(OverlayKind::TrackerPage)
        );

        let mut four = app(&p);
        four.screen = Screen::Tracker;
        four.controller_layout = ControllerLayout::Four;
        tx.send(MidiEvent::Encoder(crate::pads::EncoderAction::Select))
            .unwrap();
        tx.send(MidiEvent::Encoder(crate::pads::EncoderAction::Down))
            .unwrap();
        drain(&rx, &mut four, Path::new("/none"), &tx);
        assert!(four.page_select_mode);
        assert_eq!(four.menu_page(), 1);
        tx.send(MidiEvent::Encoder(crate::pads::EncoderAction::Select))
            .unwrap();
        tx.send(MidiEvent::Encoder(crate::pads::EncoderAction::Down))
            .unwrap();
        drain(&rx, &mut four, Path::new("/none"), &tx);
        assert!(!four.page_select_mode);
        assert_eq!(four.tracker_track, 0);
        assert_eq!(
            four.tracker_row, 1,
            "a stopped FT2 transport leaves normal row navigation available"
        );
    }

    #[test]
    fn ft2_rotary_always_moves_rows_and_shift_rotary_moves_columns() {
        let p = presets();
        let (tx, _rx) = mpsc::channel();
        let mut a = app(&p);
        fill_demo_song(&mut a);
        a.screen = Screen::Tracker;
        a.tracker_mode = TrackerMode::Play;
        a.tracker_order = 2;
        a.tracker_row = 9;
        a.tracker_page = 0;
        a.tracker_track = LANES_PER_PAGE - 1;

        // Remembered Play mode is still paused, so the rotary moves rows.
        dispatch_encoder(
            crate::pads::EncoderAction::Down,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!((a.tracker_page, a.tracker_track), (0, LANES_PER_PAGE - 1));
        assert_eq!((a.tracker_order, a.tracker_row), (2, 10));

        a.sequencer.play(&a.song, a.tracker_order, a.tracker_row);
        let transport = a.sequencer.status();
        dispatch_encoder(
            crate::pads::EncoderAction::Down,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!((a.tracker_page, a.tracker_track), (0, LANES_PER_PAGE - 1));
        assert_eq!((a.tracker_order, a.tracker_row), (2, 11));
        assert_eq!(a.sequencer.status().playing, transport.playing);
        assert_eq!(a.sequencer.status().order, transport.order);
        assert_eq!(a.sequencer.status().row, transport.row);

        dispatch_modified_encoder(
            crate::pads::EncoderAction::Down,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!((a.tracker_page, a.tracker_track), (1, 0));
        assert_eq!(a.tracker_row, 11);

        a.sequencer.stop();
        a.tracker_mode = TrackerMode::Edit;
        dispatch_encoder(
            crate::pads::EncoderAction::Down,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!((a.tracker_page, a.tracker_track), (1, 0));
        assert_eq!(a.tracker_row, 12);
        dispatch_modified_encoder(
            crate::pads::EncoderAction::Up,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!((a.tracker_page, a.tracker_track), (0, LANES_PER_PAGE - 1));
        assert_eq!(a.tracker_row, 12);
    }

    #[test]
    fn ft2_shift_rotary_crosses_both_page_boundaries_without_moving_other_state() {
        let p = presets();
        let (tx, _rx) = mpsc::channel();
        let mut a = app(&p);
        fill_demo_song(&mut a);
        a.screen = Screen::Tracker;
        a.tracker_mode = TrackerMode::Play;
        a.tracker_order = 2;
        a.tracker_row = 9;
        a.arrange_selected = 3;
        a.sequencer.play(&a.song, 1, 4);
        let transport = a.sequencer.status();
        let order = a.song.order.clone();

        for (page, expected) in [(0, (1, 0)), (1, (2, 0))] {
            a.tracker_page = page;
            a.tracker_track = LANES_PER_PAGE - 1;
            dispatch_modified_encoder(
                crate::pads::EncoderAction::Down,
                &mut a,
                Path::new("/none"),
                &tx,
            );
            assert_eq!((a.tracker_page, a.tracker_track), expected);
        }
        for (page, expected) in [(2, (1, LANES_PER_PAGE - 1)), (1, (0, LANES_PER_PAGE - 1))] {
            a.tracker_page = page;
            a.tracker_track = 0;
            dispatch_modified_encoder(
                crate::pads::EncoderAction::Up,
                &mut a,
                Path::new("/none"),
                &tx,
            );
            assert_eq!((a.tracker_page, a.tracker_track), expected);
        }

        assert_eq!(a.tracker_row, 9);
        assert_eq!(a.tracker_mode, TrackerMode::Play);
        assert_eq!(a.tracker_order, 2);
        assert_eq!(a.arrange_selected, 3);
        assert_eq!(a.song.order, order);
        assert_eq!(a.sequencer.status().playing, transport.playing);
        assert_eq!(a.sequencer.status().order, transport.order);
        assert_eq!(a.sequencer.status().row, transport.row);
    }

    #[test]
    fn ft2_record_shift_rotary_ignores_turns_until_every_recorded_note_is_off() {
        let p = presets();
        let (tx, _rx) = mpsc::channel();
        let mut a = app(&p);
        fill_demo_song(&mut a);
        a.screen = Screen::Tracker;
        a.tracker_mode = TrackerMode::Rec;
        a.tracker_row = 7;
        a.tracker_page = 0;
        a.tracker_track = LANES_PER_PAGE - 1;
        a.tracker_recording = Some(TrackerRecording {
            pattern: 0,
            order: 0,
            page: 0,
            return_to_play: false,
            last_row: 7,
            next_lane: LANES_PER_PAGE - 1,
            active_lanes: HashMap::from([(
                (0, 60),
                vec![RecordedLane {
                    pattern: 0,
                    order: 0,
                    page: 0,
                    lane: LANES_PER_PAGE - 1,
                    start_row: 7,
                    token: 1,
                }],
            )]),
            lane_owners: HashMap::from([((0, LANES_PER_PAGE - 1), 1)]),
            next_token: 2,
            notes: 1,
        });

        for _ in 0..2 {
            dispatch_modified_encoder(
                crate::pads::EncoderAction::Down,
                &mut a,
                Path::new("/none"),
                &tx,
            );
        }
        assert_eq!((a.tracker_page, a.tracker_track), (0, LANES_PER_PAGE - 1));
        assert_eq!(a.tracker_row, 7);

        a.record_tracker_midi(&[0x80, 60, 0]);
        dispatch_modified_encoder(
            crate::pads::EncoderAction::Down,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!((a.tracker_page, a.tracker_track), (1, 0));
        let recording = a.tracker_recording.as_ref().unwrap();
        assert_eq!(
            (recording.pattern, recording.order, recording.page),
            (0, 0, 1)
        );
        assert_eq!(recording.next_lane, 0);
        assert_eq!(recording.notes, 1);
        assert_eq!(a.tracker_row, 7);
        assert_eq!(a.tracker_mode, TrackerMode::Rec);
    }

    #[test]
    fn shift_rotary_uses_each_existing_secondary_axis_without_triggering_work() {
        let p = presets();
        let (tx, _rx) = mpsc::channel();
        let mut a = app(&p);
        enable_all_test_catalogs(&mut a, &p);

        a.screen = Screen::Presets;
        a.selected = 1;
        let first_backend = a.selected_backend();
        dispatch_modified_encoder(
            crate::pads::EncoderAction::Down,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_ne!(a.selected_backend(), first_backend);
        assert_eq!(a.selected, 0);
        assert!(a.engine.is_none());
        assert!(a.engine_owner.is_none());
        assert!(a.playing.is_none());
        dispatch_modified_encoder(
            crate::pads::EncoderAction::Up,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!(a.selected_backend(), first_backend);
        assert!(a.engine.is_none());

        a.screen = Screen::TrackerPages;
        a.page_manager_mode = PageManagerMode::Pages;
        a.tracker_page = 1;
        a.tracker_track = 1;
        dispatch_modified_encoder(
            crate::pads::EncoderAction::Down,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!((a.tracker_page, a.tracker_track), (1, 2));

        a.screen = Screen::LivePatterns;
        a.tracker_page = 0;
        a.tracker_track = 1;
        dispatch_modified_encoder(
            crate::pads::EncoderAction::Down,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!((a.tracker_page, a.tracker_track), (0, 2));

        a.screen = Screen::TrackerLoop;
        a.loop_slot_selected = 0;
        dispatch_modified_encoder(
            crate::pads::EncoderAction::Up,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!(a.loop_slot_selected, crate::loop_player::LOOP_SLOTS - 1);

        a.screen = Screen::TrackerFiles;
        a.tracker_files_mode = TrackerFilesMode::Drums;
        a.drum_patterns = ["Jazz", "Rock"]
            .into_iter()
            .map(|genre| drum_pattern::Entry {
                name: format!("{genre} test"),
                genre: genre.into(),
                meter: 4,
                rows: 32,
                path: PathBuf::from(format!("{genre}.shdrum")),
                user: false,
                bundled: None,
            })
            .collect();
        a.drum_meter = 4;
        a.drum_target_rows = 32;
        a.drum_genre_selected = 0;
        dispatch_modified_encoder(
            crate::pads::EncoderAction::Down,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!(a.drum_genre_selected, 1);

        a.screen = Screen::FxRack;
        a.fx_target = 0;
        dispatch_modified_encoder(
            crate::pads::EncoderAction::Up,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!(a.fx_target, FX_TARGET_COUNT - 1);

        a.screen = Screen::MasterStripAdvanced;
        a.master_strip_section = MasterStripSection::Input;
        a.master_strip_parameter = 1;
        dispatch_modified_encoder(
            crate::pads::EncoderAction::Up,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!(a.master_strip_section, MasterStripSection::Loud);
        assert_eq!(
            a.master_strip_parameter, 0,
            "the existing section action owns its parameter reset"
        );
    }

