    #[test]
    fn route_editor_channel_ten_commit_prepares_drums_before_reenabling_live_input() {
        let p = presets();
        let mut a = app(&p);
        let (tx, _rx) = mpsc::channel();
        a.screen = Screen::Tracker;
        a.tracker_page = 2;
        a.tracker_track = 0;
        for column in &mut a.current_page_mut().unwrap().columns {
            column.channel = 8;
        }
        assert!(a.sync_tracker_route());
        assert_eq!(
            a.engine.as_ref().unwrap().test_fluidsynth_selection(8),
            Some((128, 0))
        );
        assert_eq!(
            a.engine.as_ref().unwrap().test_fluidsynth_selection(9),
            None
        );

        a.set_tracker_edit(true);
        controller_select_page(&mut a, ControllerLayout::Eight, 2, &tx);
        dispatch_pad(
            crate::pads::PadAction::Item2,
            true,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        assert_eq!(
            a.overlay.as_ref().map(|overlay| overlay.kind),
            Some(OverlayKind::TrackerRoute)
        );
        for _ in 0..5 {
            dispatch_encoder(
                crate::pads::EncoderAction::Down,
                &mut a,
                Path::new("/none"),
                &tx,
            );
        }
        dispatch_encoder(
            crate::pads::EncoderAction::Select,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        dispatch_encoder(
            crate::pads::EncoderAction::Down,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        dispatch_encoder(
            crate::pads::EncoderAction::Select,
            &mut a,
            Path::new("/none"),
            &tx,
        );
        for _ in 0..16 {
            dispatch_encoder(
                crate::pads::EncoderAction::Down,
                &mut a,
                Path::new("/none"),
                &tx,
            );
        }
        dispatch_encoder(
            crate::pads::EncoderAction::Select,
            &mut a,
            Path::new("/none"),
            &tx,
        );

        assert!(a.overlay.is_none());
        assert_eq!(a.current_page().unwrap().column(0).channel, 9);
        assert_eq!(
            a.engine.as_ref().unwrap().test_fluidsynth_selection(9),
            Some((128, 0))
        );
        assert!(a.tracker_route.lock().unwrap().preview_state().0);
        assert!(a
            .tracker_route
            .lock()
            .unwrap()
            .destinations()
            .iter()
            .any(|(_, channel)| *channel == 9));
    }

    #[test]
    fn saved_or_nondefault_empty_project_never_adopts_the_player_route() {
        let p = presets();
        let explicit = SoftwareRoute::synthv1("Preset 17");
        let mut saved = app(&p);
        saved.current_pattern_mut().unwrap().pages[0].target =
            PageTarget::Software(explicit.clone());
        saved.song_file_stem = Some("saved-empty".into());
        saved.tracker_page = 1;
        saved.tracker_track = 3;
        saved.tracker_row = 11;
        saved.tracker_order = 0;
        saved.screen = Screen::Playback;
        saved.engine = Some(
            Engine::start_test_process(BackendKind::Synthv1, Arc::clone(&saved.midi_output))
                .unwrap(),
        );
        saved.playing = Some(p[38].clone());
        saved.engine_owner = Some(EngineOwner::SoftwareSynth);

        perform(Action::OpenTracker, &mut saved, Path::new("/none"), None);

        assert_eq!(
            saved.song.patterns[&0].pages[0].target,
            PageTarget::Software(explicit.clone())
        );
        assert_eq!(
            (saved.tracker_page, saved.tracker_track, saved.tracker_row),
            (1, 3, 11)
        );
        assert!(!sequencer::pattern_has_note_events(
            &saved.song.patterns[&0]
        ));

        let mut unsaved = app(&p);
        unsaved.current_pattern_mut().unwrap().pages[0].target =
            PageTarget::Software(explicit.clone());
        unsaved.screen = Screen::Playback;
        unsaved.engine = Some(
            Engine::start_test_process(BackendKind::Synthv1, Arc::clone(&unsaved.midi_output))
                .unwrap(),
        );
        unsaved.playing = Some(p[38].clone());
        unsaved.engine_owner = Some(EngineOwner::SoftwareSynth);
        unsaved.tracker_engine_start_override = Some(Ok(()));

        perform(Action::OpenTracker, &mut unsaved, Path::new("/none"), None);

        assert_eq!(
            unsaved.song.patterns[&0].pages[0].target,
            PageTarget::Software(explicit)
        );
        assert_eq!(
            unsaved.engine_owner,
            Some(EngineOwner::Tracker(SoftwareRoute::synthv1("Preset 17")))
        );
    }

    #[test]
    fn arrangement_refuses_two_single_preset_backend_sounds() {
        let p = presets();
        let mut a = app(&p);
        let empty = sequencer::schedule(&a.song, &a.config.external_midi, 0, 0).unwrap();
        assert_eq!(scheduled_software_plan(&empty).unwrap(), None);

        a.song.patterns.get_mut(&0).unwrap().rows[0][0].note = Note::On(60);
        let one_route = sequencer::schedule(&a.song, &a.config.external_midi, 0, 0).unwrap();
        assert_eq!(
            scheduled_software_plan(&one_route)
                .unwrap()
                .and_then(|plan| plan.primary_route().cloned()),
            Some(SoftwareRoute::synthv1("Preset 00")),
        );
        let mut second = a.song.patterns[&0].pages[0].clone();
        second.name = "SECOND SYNTH".into();
        second.target = PageTarget::Software(SoftwareRoute::synthv1("Preset 01"));
        let pattern = a.song.patterns.get_mut(&0).unwrap();
        let second_page_lane = pattern.pages.len() * LANES_PER_PAGE;
        pattern.pages.push(second);
        for row in &mut pattern.rows {
            row.extend([Cell::default(); LANES_PER_PAGE]);
        }
        pattern.rows[0][second_page_lane].note = Note::On(64);
        let two_routes = sequencer::schedule(&a.song, &a.config.external_midi, 0, 0).unwrap();
        assert!(scheduled_software_plan(&two_routes)
            .unwrap_err()
            .to_string()
            .contains("exposes one preset"));
    }

    fn fluid_route(instrument: &str) -> SoftwareRoute {
        SoftwareRoute {
            engine: BackendKind::FluidSynth,
            instrument: instrument.into(),
        }
    }

    fn planned_note(
        route: SoftwareRoute,
        channel: u8,
        note: u8,
        lane: usize,
    ) -> sequencer::ScheduledMessage {
        sequencer::ScheduledMessage {
            at: Duration::ZERO,
            bytes: vec![0x90 | channel, note, 100],
            order: 0,
            row: 0,
            lane: Some(lane),
            target: Some(PageTarget::Software(route)),
        }
    }

    #[test]
    fn fluidsynth_multipart_plan_accepts_bass_keys_pad_and_channel_ten_drums() {
        let messages = vec![
            planned_note(fluid_route("sf0:band.sf2:0:32"), 0, 36, 0),
            planned_note(fluid_route("sf0:band.sf2:0:4"), 1, 60, 4),
            planned_note(fluid_route("sf1:pads.sf2:0:89"), 2, 67, 8),
            planned_note(fluid_route("sf0:band.sf2:128:0"), 9, 36, 12),
        ];
        let plan = scheduled_software_plan(&messages).unwrap().unwrap();
        assert_eq!(plan.parts.len(), 4);
        let mut channels = plan
            .parts
            .iter()
            .map(|part| part.channel)
            .collect::<Vec<_>>();
        channels.sort_unstable();
        assert_eq!(channels, [0, 1, 2, 9]);
    }

    #[test]
    fn internal_drums_do_not_consume_or_replace_the_melodic_software_plan() {
        let melodic = SoftwareRoute::synthv1("Preset 00");
        let messages = vec![
            planned_note(melodic.clone(), 0, 60, 0),
            sequencer::ScheduledMessage {
                target: Some(PageTarget::InternalDrums("electronic-house".into())),
                bytes: vec![0x99, 36, 100],
                ..planned_note(fluid_route("ignored"), 9, 36, 8)
            },
        ];
        let plan = scheduled_software_plan(&messages).unwrap().unwrap();
        assert_eq!(plan.parts.len(), 1);
        assert!(plan.contains_part(&melodic, 0));
    }

    #[test]
    fn fluidsynth_plan_deduplicates_shared_route_channel_without_dropping_notes() {
        let route = fluid_route("sf0:band.sf2:0:32");
        let messages = (0..8)
            .map(|lane| planned_note(route.clone(), 0, 36 + lane as u8, lane))
            .collect::<Vec<_>>();
        let plan = scheduled_software_plan(&messages).unwrap().unwrap();
        assert_eq!(plan.parts.len(), 1);
        assert_eq!(
            messages
                .iter()
                .filter(|message| message.bytes[0] & 0xf0 == 0x90)
                .count(),
            8
        );
    }

    #[test]
    fn fluidsynth_same_preset_can_occupy_several_channels() {
        let route = fluid_route("sf0:band.sf2:0:32");
        let messages = vec![
            planned_note(route.clone(), 0, 36, 0),
            planned_note(route.clone(), 1, 40, 1),
            planned_note(route, 9, 42, 2),
        ];
        let plan = scheduled_software_plan(&messages).unwrap().unwrap();
        assert_eq!(plan.parts.len(), 3);
    }

    #[test]
    fn fluidsynth_conflicting_stable_channel_assignments_are_clear() {
        let error = scheduled_software_plan(&[
            planned_note(fluid_route("sf0:band.sf2:0:32"), 0, 36, 0),
            planned_note(fluid_route("sf1:other.sf2:0:48"), 0, 60, 4),
        ])
        .unwrap_err()
        .to_string();
        assert!(error.contains("FluidSynth channel 1"));
        assert!(error.contains("one stable preset per channel"));
    }

    #[test]
    fn fluidsynth_with_external_midi_is_valid_but_mixed_software_backends_are_not() {
        let mut fluid_and_external = vec![planned_note(fluid_route("sf0:band.sf2:0:32"), 0, 36, 0)];
        fluid_and_external.push(sequencer::ScheduledMessage {
            target: Some(PageTarget::Midi("DIN".into())),
            ..planned_note(fluid_route("ignored"), 4, 60, 4)
        });
        assert_eq!(
            scheduled_software_plan(&fluid_and_external)
                .unwrap()
                .unwrap()
                .parts
                .len(),
            1
        );

        let mixed = [
            planned_note(fluid_route("sf0:band.sf2:0:32"), 0, 36, 0),
            planned_note(SoftwareRoute::synthv1("Bass"), 1, 60, 4),
        ];
        assert!(scheduled_software_plan(&mixed)
            .unwrap_err()
            .to_string()
            .contains("mixes software backends"));
    }

